// Emit one item per keyword bucket. Fetch Jooble runs once per item.
// IMPORTANT: Jooble matches location on COUNTRY reliably; "Jeddah" alone
// returns 0 results, so we query "Saudi Arabia" and let Merge keep Saudi rows.
// Broad keyword coverage (engineering + general + sales + part-time) drives
// volume toward the 100/day target.
const buckets = [
  'engineer OR industrial OR mechanical OR operations',
  'supply chain OR logistics OR procurement OR warehouse',
  'process OR quality OR lean OR production OR maintenance',
  'sales OR sales representative OR business development',
  'retail OR store OR merchandiser OR cashier',
  'customer service OR call center OR support OR receptionist',
  'coordinator OR administrator OR assistant OR data entry',
  'part time OR night shift OR driver OR delivery OR security',
];
return buckets.map((k) => ({ json: { keywords: k, location: 'Saudi Arabia', date: '7', page: '1' } }));

const stripHtml = (s) => String(s || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#0?39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

// location relevance: whole-word match only (avoid "ksa" matching inside
// German compound words). Accept genuine Saudi/Jeddah signals.
const ACCEPT = ['saudi', 'saudi arabia', 'jeddah', 'ksa', 'riyadh', 'makkah', 'mecca', 'dammam', 'khobar', 'jubail', 'medina', 'madinah', 'جدة', 'السعودية'];
const hasWord = (text, term) => {
  const t = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^\\p{L}0-9])' + t + '([^\\p{L}0-9]|$)', 'iu').test(text);
};
const locationOk = (loc, desc) => {
  const hay = String(loc || '') + ' ' + String(desc || '');
  return ACCEPT.some((k) => hasWord(hay, k));
};

// Jooble (and similar) URLs carry per-run tracking query params (elckey, aq,
// pos, scr...) that change every run, so the SAME job produces a different full
// URL each time. Dedup on a normalized key: strip the query string so the
// stable path (e.g. jooble.org/desc/<id>) is what we compare on.
const normUrl = (u) => String(u || '').trim().split('?')[0].replace(/\/+$/, '').toLowerCase();

// existing job keys (dedup against table)
const existingUrls = new Set();
try {
  for (const it of $('Get Existing Jobs').all()) {
    const u = it.json && it.json.job_url ? normUrl(it.json.job_url) : '';
    if (u) existingUrls.add(u);
  }
} catch (e) {}

const seen = new Set();
const out = [];
const push = (title, company, desc, url, loc) => {
  const t = String(title || '').trim();
  const u = String(url || '').trim();
  if (!t || !u) return;
  const key = normUrl(u);
  const cleanDesc = stripHtml(desc);
  if (!cleanDesc || cleanDesc.length < 20) return;
  if (!locationOk(loc, cleanDesc)) return;
  if (existingUrls.has(key) || seen.has(key)) return;
  seen.add(key);
  out.push({ json: {
    job_title: t,
    company: String(company || 'Unknown').trim(),
    job_description: cleanDesc,
    location: String(loc || 'Saudi Arabia').trim(),
    job_url: u,
    contact_email: '',
    status: 'new',
    job_type: 'general',
    industry: 'General',
  }});
};

// Jooble (runs once per keyword bucket) -> resp.jobs[]
try {
  for (const r of $('Fetch Jooble').all()) {
    const resp = r.json || {};
    const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
    for (const j of jobs) push(j.title, j.company || j.source, j.snippet, j.link, j.location);
  }
} catch (e) {}

return out;

// Fill contact_email for jobs that have none, by matching the job's title +
// description keywords against each agency's specialties. Jobs that ALREADY
// have a contact_email pass through UNCHANGED (existing path). Load is spread
// across agencies (per-agency cap + least-loaded pick) so no single agency
// inbox gets flooded in one run — important for deliverability / warm-up.
const jobs = $('Merge & Dedup').all().map((i) => i.json || {});
const agencies = $('Get Agencies').all()
  .map((i) => i.json || {})
  .filter((a) => a && a.contact_email && String(a.contact_email).trim())
  .map((a) => ({
    name: String(a.agency_name || 'Agency').trim(),
    email: String(a.contact_email).trim(),
    region: String(a.region || 'Saudi Arabia').trim(),
    specialties: String(a.specialties || '')
      .toLowerCase()
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean),
    assigned: 0,
  }));

const PER_AGENCY_CAP = 3; // max jobs routed to one agency per run

const out = [];
for (const j of jobs) {
  // Existing path: job already has an email -> keep untouched.
  if (j.contact_email && String(j.contact_email).trim()) {
    out.push({ json: j });
    continue;
  }

  const hay = (String(j.job_title || '') + ' ' + String(j.job_description || '')).toLowerCase();

  // Score every agency by how many of its specialty terms appear in the job.
  const matches = [];
  for (const a of agencies) {
    let score = 0;
    for (const sp of a.specialties) {
      if (sp && hay.includes(sp)) score++;
    }
    if (score > 0) matches.push({ a, score });
  }

  if (!matches.length) {
    // No agency specialty matched: keep row as-is (no email). It is still
    // inserted like before, but the applier cannot email it. This preserves
    // the original behaviour and never fabricates an email.
    out.push({ json: j });
    continue;
  }

  // Prefer under-cap agencies; among candidates pick highest specialty score,
  // then least-loaded, to spread volume.
  const underCap = matches.filter((m) => m.a.assigned < PER_AGENCY_CAP);
  const pool = underCap.length ? underCap : matches;
  pool.sort((x, y) => (y.score - x.score) || (x.a.assigned - y.a.assigned));
  const pick = pool[0].a;
  pick.assigned++;

  out.push({ json: {
    ...j,
    contact_email: pick.email,
    location: j.location || pick.region,
    job_description: String(j.job_description || '').trim() + ' [via agency: ' + pick.name + ']',
    status: 'new',
    job_type: 'general',
  }});
}

return out;
